public class RandomStringUtils_random_TriageGen1Test {







    @Test
    public void testRandom_DefaultRangeWithLettersOrNumbers() {
        // start=0, end=0, letters=true -> end becomes 'z' + 1, start becomes ' '
        // This tests the branch: else { end = 'z' + 1; start = ' '; }
        String result = RandomStringUtils.random(5, 0, 0, true, false, null, new Random());
        assertEquals(5, result.length());
    }












}

package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Random;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class RandomStringUtils_random_TriageGen1Test {









    @Test
    public void testRandom_WithCharsArray() {
        char[] chars = {'a', 'b', 'c'};
        // gap = 3 - 0 = 3. random.nextInt(3) + 0
        String result = RandomStringUtils.random(5, 0, 3, false, false, chars, new Random());
        assertEquals(5, result.length());
        for (char c : result.toCharArray()) {
            assertTrue(c == 'a' || c == 'b' || c == 'c');
        }
    }










}

package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Random;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class RandomStringUtils_random_TriageGen1Test {











    @Test
    public void testRandom_FilterLogic() {
        // Test filtering: letters=true, numbers=false
        // We use a range that includes both to ensure the 'else { count++; }' branch is hit
        char[] mixed = {'a', '1'};
        String result = RandomStringUtils.random(5, 0, 2, true, false, mixed, new Random());
        assertEquals(5, result.length());
        for (char c : result.toCharArray()) {
            assertTrue(Character.isLetter(c));
        }
    }








}

package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Random;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class RandomStringUtils_random_TriageGen1Test {













    @Test
    public void testRandom_SurrogatePairs_HighSurrogate() {
        // Test the branch: else if(ch >= 55296 && ch <= 56191) [High Surrogate]
        // High surrogate range: 0xD800 to 0xDBFF
        // When high surrogate is picked, it inserts low surrogate before and decrements count
        char[] highSurrogateOnly = {(char) 55296}; 
        // Note: The logic in the provided code for high surrogate is:
        // buffer[count] = (char) (56320 + random.nextInt(128));
        // buffer[count] = ch;
        // This creates a pair.

        // To trigger the "count == 0" edge case in surrogates, we need count=1
        // But the code does buffer[count] = ... and count--. 
        // If count is 0, it does count++.
        String result = RandomStringUtils.random(1, 0, 1, false, false, highSurrogateOnly, new Random());
        assertNotNull(result);
    }






}

