public class RandomStringUtils_random_TriageGen1Test {















    @Test
    public void testRandom_SurrogatePairs_LowSurrogate() {
        // Test the branch: if(ch >= 56320 && ch <= 57343) [Low Surrogate]
        char[] lowSurrogateOnly = {(char) 56320};
        String result = RandomStringUtils.random(5, 0, 1, false, false, lowSurrogateOnly, new Random());
        // The code logic for low surrogate:
        // buffer[count] = ch;
        // count--;
        // buffer[count] = (char) (55296 + random.nextInt(128));
        // This effectively creates a high-low pair.
        assertNotNull(result);
    }




}

package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Random;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class RandomStringUtils_random_TriageGen1Test {

















    @Test
    public void testRandom_PrivateSurrogate() {
        // Test the branch: else if(ch >= 56192 && ch <= 56319) [Private Surrogate]
        // This branch simply does count++ (skips the character)
        char[] privateSurrogate = {(char) 56200};
        String result = RandomStringUtils.random(5, 0, 1, false, false, privateSurrogate, new Random());
        // Since it keeps skipping, if we provide only this, it might loop. 
        // However, in a real test, we'd mix it.
        char[] mixed = {'a', (char) 56200};
        result = RandomStringUtils.random(5, 0, 2, false, false, mixed, new Random());
        assertEquals(5, result.length());
    }


}

package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Random;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class RandomStringUtils_random_TriageGen1Test {



















    @Test
    public void testRandom_AllFlagsFalse() {
        // Tests the branch: if (letters && Character.isLetter(ch) || numbers && Character.isDigit(ch) || !letters && !numbers)
        // When both are false, it should accept any char that isn't a surrogate/private surrogate
        char[] chars = {'!', '@', '#'};
        String result = RandomStringUtils.random(5, 0, 3, false, false, chars, new Random());
        assertEquals(5, result.length());
    }
}
